CREATE TABLE IF NOT EXISTS asset_clearance_orchestrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, orchestration_version integer NOT NULL DEFAULT 1, overall_status text NOT NULL DEFAULT 'Not Ready', investment_readiness text NOT NULL DEFAULT 'Blocked', legal_readiness text NOT NULL DEFAULT 'Not Assessed', evidence_readiness text NOT NULL DEFAULT 'Not Assessed', community_readiness text NOT NULL DEFAULT 'Not Assessed', environmental_readiness text NOT NULL DEFAULT 'Not Assessed', regulatory_readiness text NOT NULL DEFAULT 'Not Assessed', survey_readiness text NOT NULL DEFAULT 'Not Assessed', shared_value_readiness text NOT NULL DEFAULT 'Not Assessed', blocker_count integer NOT NULL DEFAULT 0, warning_count integer NOT NULL DEFAULT 0, confidence_score numeric(6,2), primary_blocker text, next_action_summary text, decision_rationale text, assessed_at timestamptz NOT NULL DEFAULT now(), assessor_reference text, status text NOT NULL DEFAULT 'Active', UNIQUE(asset_id,orchestration_version));
CREATE TABLE IF NOT EXISTS asset_clearance_gates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), orchestration_id uuid NOT NULL REFERENCES asset_clearance_orchestrations(id) ON DELETE CASCADE, gate_code text NOT NULL, gate_name text NOT NULL, status text NOT NULL DEFAULT 'Not Assessed', blocking boolean NOT NULL DEFAULT false, confidence_score numeric(6,2), rationale text, evidence_reference text, source_system text, next_action text, owner_reference text, due_date date, evaluated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(orchestration_id,gate_code));
CREATE TABLE IF NOT EXISTS asset_clearance_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), orchestration_id uuid NOT NULL REFERENCES asset_clearance_orchestrations(id) ON DELETE CASCADE, gate_id uuid REFERENCES asset_clearance_gates(id) ON DELETE SET NULL, action_type text NOT NULL DEFAULT 'Remediation', action_title text NOT NULL, action_description text NOT NULL, priority text NOT NULL DEFAULT 'High', owner_reference text, due_date date, action_status text NOT NULL DEFAULT 'Open', evidence_required text, completed_at timestamptz, completion_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_clearance_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), orchestration_id uuid NOT NULL REFERENCES asset_clearance_orchestrations(id) ON DELETE CASCADE, decision_type text NOT NULL, decision text NOT NULL, rationale text NOT NULL, blocking boolean NOT NULL DEFAULT false, authority_reference text, evidence_reference text, decided_at timestamptz NOT NULL DEFAULT now(), supersedes_decision_id uuid REFERENCES asset_clearance_decisions(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Recorded');
CREATE INDEX IF NOT EXISTS idx_clearance_orch_asset ON asset_clearance_orchestrations(asset_id,assessed_at DESC);
CREATE INDEX IF NOT EXISTS idx_clearance_gates_orch ON asset_clearance_gates(orchestration_id,blocking,status);
CREATE INDEX IF NOT EXISTS idx_clearance_actions_orch ON asset_clearance_actions(orchestration_id,action_status,priority);
CREATE INDEX IF NOT EXISTS idx_clearance_decisions_orch ON asset_clearance_decisions(orchestration_id,decided_at DESC);